import{_ as r,C as l,o as e,c as n,a2 as o,b as d,w as i,a as s,E as c,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const A=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md"}'),m={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md"};function p(g,a,f,b,h,P){const t=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-v" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre V) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-v" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre V)&quot;">​</a></h2><h3 id="eje-tematico-metodologias-de-desarrollo-de-software-para-el-pst-ii" tabindex="-1">Eje Temático: Metodologías de Desarrollo de Software para el PST II <a class="header-anchor" href="#eje-tematico-metodologias-de-desarrollo-de-software-para-el-pst-ii" aria-label="Permalink to &quot;Eje Temático: Metodologías de Desarrollo de Software para el PST II&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-disciplina-del-desarrollo-de-software" tabindex="-1">🧭 Introducción: La Disciplina del Desarrollo de Software <a class="header-anchor" href="#🧭-introduccion-la-disciplina-del-desarrollo-de-software" aria-label="Permalink to &quot;🧭 Introducción: La Disciplina del Desarrollo de Software&quot;">​</a></h2><p>El desarrollo de software no consiste simplemente en sentarse frente al teclado a escribir código sin rumbo (&quot;programar y corregir&quot;). La <strong>Ingeniería de Software</strong> proporciona metodologías, procesos y estándares que permiten transformar una idea o necesidad comunitaria en un producto de software confiable, mantenible y entregado a tiempo.</p><p>En el Proyecto Sociotecnológico II (PST II), los estudiantes deben seleccionar, adaptar y justificar una metodología de desarrollo que se ajuste a:</p><ul><li>La naturaleza del equipo de trabajo (grupos de 3 a 5 estudiantes).</li><li>El nivel de interacción y disponibilidad de los actores comunitarios.</li><li>Los tiempos académicos trimestrales.</li><li>El marco de soberanía tecnológica e interoperabilidad nacional.</li></ul><hr><h2 id="🏛️-capitulo-i-clasificacion-de-metodologias-tradicionales-vs-agiles" tabindex="-1">🏛️ CAPÍTULO I: Clasificación de Metodologías: Tradicionales vs. Ágiles <a class="header-anchor" href="#🏛️-capitulo-i-clasificacion-de-metodologias-tradicionales-vs-agiles" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Clasificación de Metodologías: Tradicionales vs. Ágiles&quot;">​</a></h2><p>Existen dos grandes paradigmas en el desarrollo de software:</p>',11)),(e(),d(u,null,{default:i(()=>[c(t,{id:"mermaid-48",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20M%5B%22%E2%9A%99%EF%B8%8F%20Paradigmas%20de%20Desarrollo%20de%20Software%22%5D%0A%20%20%20%20M%20--%3E%20T%5B%22%F0%9F%8F%9B%EF%B8%8F%20Metodolog%C3%ADas%20Tradicionales%20%2F%20Robustas%22%5D%0A%20%20%20%20M%20--%3E%20A%5B%22%E2%9A%A1%20Metodolog%C3%ADas%20%C3%81giles%20%2F%20Adaptativas%22%5D%0A%0A%20%20%20%20T%20--%3E%20T1%5B%22Cascada%20(Waterfall)%22%5D%0A%20%20%20%20T%20--%3E%20T2%5B%22Proceso%20Unificado%20de%20Rational%20(RUP)%22%5D%0A%20%20%20%20T%20--%3E%20T3%5B%22Espiral%20y%20Desarrollo%20Incremental%22%5D%0A%0A%20%20%20%20A%20--%3E%20A1%5B%22Scrum%20(Sprints%20y%20Roles)%22%5D%0A%20%20%20%20A%20--%3E%20A2%5B%22Extreme%20Programming%20-%20XP%20(TDD%20y%20Parejas)%22%5D%0A%20%20%20%20A%20--%3E%20A3%5B%22Kanban%20(Flujo%20Continuo)%22%5D%0A%0A%20%20%20%20style%20M%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20T%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20A%20fill%3A%23064e3b%2Cstroke%3A%2310b981%2Ccolor%3A%23fff%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="_1-1-metodologias-tradicionales-predictivas-dirigidas-por-plan" tabindex="-1">1.1 Metodologías Tradicionales (Predictivas / Dirigidas por Plan) <a class="header-anchor" href="#_1-1-metodologias-tradicionales-predictivas-dirigidas-por-plan" aria-label="Permalink to &quot;1.1 Metodologías Tradicionales (Predictivas / Dirigidas por Plan)&quot;">​</a></h3><p>Se basan en una planificación exhaustiva, estricta disciplina secuencial y documentación detallada antes de comenzar la codificación.</p><ul><li><strong>RUP (Rational Unified Process):</strong> Se organiza en 4 fases (Inicio, Elaboración, Construcción, Transición) y disciplinas (Requerimientos, Análisis, Diseño, Implementación, Pruebas).</li><li><em>Ventaja:</em> Documentación exhaustiva y control riguroso de la arquitectura.</li><li><em>Desventaja:</em> Muy burocráticas y poco tolerantes a cambios de última hora solicitados por la comunidad.</li></ul><h3 id="_1-2-metodologias-agiles-adaptativas-guiadas-por-valor" tabindex="-1">1.2 Metodologías Ágiles (Adaptativas / Guiadas por Valor) <a class="header-anchor" href="#_1-2-metodologias-agiles-adaptativas-guiadas-por-valor" aria-label="Permalink to &quot;1.2 Metodologías Ágiles (Adaptativas / Guiadas por Valor)&quot;">​</a></h3><p>Nacidas formalmente con el <strong>Manifiesto Ágil (2001)</strong>, priorizan el software funcionando por encima de la documentación exhaustiva, la colaboración con el cliente por encima de la negociación contractual, y la respuesta ante el cambio por encima del seguimiento ciego de un plan.</p><ul><li><strong>Scrum:</strong> Gestión iterativa basada en <em>Sprints</em> (ciclos de 2 a 4 semanas) donde se entregan incrementos funcionales de software. Roles: <em>Product Owner</em> (representante de la comunidad/tutor), <em>Scrum Master</em> (facilitador del equipo) y <em>Development Team</em> (los estudiantes programadores).</li><li><strong>Extreme Programming (XP):</strong> Enfocada en la excelencia técnica del código: programación en parejas (<em>pair programming</em>), desarrollo guiado por pruebas (<em>Test-Driven Development - TDD</em>), refactorización continua e integración frecuente.</li></ul><hr><h2 id="🇻🇪-capitulo-ii-metodologias-de-software-libre-en-la-administracion-publica" tabindex="-1">🇻🇪 CAPÍTULO II: Metodologías de Software Libre en la Administración Pública <a class="header-anchor" href="#🇻🇪-capitulo-ii-metodologias-de-software-libre-en-la-administracion-publica" aria-label="Permalink to &quot;🇻🇪 CAPÍTULO II: Metodologías de Software Libre en la Administración Pública&quot;">​</a></h2><p>En Venezuela, el Centro Nacional de Tecnologías de Información (CNTI) y la comunidad de Software Libre desarrollaron marcos metodológicos adaptados a la realidad institucional del país:</p><h3 id="_2-1-metodologia-merinde" tabindex="-1">2.1 Metodología MERINDE <a class="header-anchor" href="#_2-1-metodologia-merinde" aria-label="Permalink to &quot;2.1 Metodología MERINDE&quot;">​</a></h3><p><strong>MERINDE</strong> (Metodología para el Desarrollo de Software Libre en Instituciones del Estado) fue concebida para orientar el ciclo de vida de proyectos tecnológicos bajo la Ley de Infogobierno:</p><ol><li><strong>Fase de Análisis de la Situación:</strong> Levantamiento de necesidades institucionales y diagnóstico.</li><li><strong>Fase de Arquitectura y Diseño:</strong> Modelado de datos e interfaces abiertas.</li><li><strong>Fase de Construcción Colaborativa:</strong> Uso de repositorios públicos de código, control de versiones libre (Git) y estándares web (W3C).</li><li><strong>Fase de Pruebas e Implantación:</strong> Verificación de seguridad, pruebas de usuario y capacitación comunitaria.</li></ol><h3 id="_2-2-metodologia-watch" tabindex="-1">2.2 Metodología WATCH <a class="header-anchor" href="#_2-2-metodologia-watch" aria-label="Permalink to &quot;2.2 Metodología WATCH&quot;">​</a></h3><p>Enfocada en el desarrollo de aplicaciones web ágiles con documentación esencial, ideal para equipos pequeños que construyen portales comunitarios o sistemas de consulta rápida.</p><hr><h2 id="⚖️-capitulo-iii-cuadro-comparativo-de-metodologias-para-pst-ii" tabindex="-1">⚖️ CAPÍTULO III: Cuadro Comparativo de Metodologías para PST II <a class="header-anchor" href="#⚖️-capitulo-iii-cuadro-comparativo-de-metodologias-para-pst-ii" aria-label="Permalink to &quot;⚖️ CAPÍTULO III: Cuadro Comparativo de Metodologías para PST II&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterio de Selección</th><th>RUP</th><th>Scrum</th><th>XP</th><th>MERINDE</th></tr></thead><tbody><tr><td><strong>Tamaño de Equipo Recomendado</strong></td><td>Mediano a Grande (&gt;10)</td><td>Pequeño (3 a 9)</td><td>Pequeño (2 a 6)</td><td>Pequeño a Mediano (3 a 8)</td></tr><tr><td><strong>Volumen de Documentación</strong></td><td>Muy Alto y Formal</td><td>Moderado (Historias de Usuario)</td><td>Mínimo técnico</td><td>Alto (Enfocado en estándares FOSS)</td></tr><tr><td><strong>Tolerancia a Cambios</strong></td><td>Baja (Requiere control de cambios)</td><td><strong>Muy Alta (Por Sprints)</strong></td><td><strong>Muy Alta (Iterativa)</strong></td><td>Media a Alta</td></tr><tr><td><strong>Curva de Aprendizaje</strong></td><td>Compleja</td><td>Sencilla y Práctica</td><td>Media (Exige disciplina de pruebas)</td><td>Adaptada a la normativa venezolana</td></tr><tr><td><strong>Idoneidad en PST II</strong></td><td>Recomendado en proyectos de alto rigor normativo</td><td><strong>Altamente Recomendado para desarrollo web/móvil</strong></td><td>Excelente para equipos con fuertes habilidades de código</td><td><strong>Ideal para justificación institucional ante el PNFI</strong></td></tr></tbody></table><hr><h2 id="🎯-capitulo-iv-como-justificar-la-metodologia-en-el-informe-de-proyecto" tabindex="-1">🎯 CAPÍTULO IV: Cómo Justificar la Metodología en el Informe de Proyecto <a class="header-anchor" href="#🎯-capitulo-iv-como-justificar-la-metodologia-en-el-informe-de-proyecto" aria-label="Permalink to &quot;🎯 CAPÍTULO IV: Cómo Justificar la Metodología en el Informe de Proyecto&quot;">​</a></h2><p>En el Capítulo II o Marco Metodológico del informe de PST II, el equipo no debe simplemente copiar la teoría de Scrum o RUP de internet. Debe <strong>contextualizarla con la realidad de su proyecto</strong>.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Estructura para la Redacción de la Justificación Metodológica:</strong></p><ol><li><strong>Definición de la Metodología Seleccionada:</strong> Breve cita teórica de autores reconocidos (Pressman, Sommerville, Schwaber &amp; Sutherland).</li><li><strong>Motivo de Selección:</strong> Justificar por qué se eligió (ejemplo: <em>&quot;Se seleccionó Scrum debido a que los requerimientos de la comunidad de regantes evolucionan rápidamente y se requiere validar con el consejo comunal entregas quincenales funcionales&quot;</em>).</li><li><strong>Adaptación de Fases al Proyecto:</strong> Cuadro donde se asocie cada fase, sprint o disciplina con las semanas del trimestre y los entregables concretos que recibirá la comunidad.</li></ol></div><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-1" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 1 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-1" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 1&quot;">​</a></h2><p>Para superar la Evaluación 1 del Trimestre V:</p><ol><li><strong>Capítulo Metodológico Redactado:</strong> Comparativa entre al menos tres metodologías y argumentación de la elegida.</li><li><strong>Matriz de Sprints o Fases:</strong> Definición clara del Backlog de Producto (Product Backlog) y distribución de entregables por cada miembro del equipo.</li></ol>',25))])}const v=r(m,[["render",p]]);export{A as __pageData,v as default};
